<?php
use FacturaFacil\Money;
$issuer = $invoice['issuer']; $customer = $invoice['customer']; $totals = $invoice['totals'];
$letter = [1=>'A',6=>'B',11=>'C'][(int)$invoice['voucher_type']];
$conditions = [1=>'IVA Responsable Inscripto',4=>'IVA Sujeto Exento',5=>'Consumidor Final',6=>'Responsable Monotributo',7=>'Sujeto no categorizado',8=>'Proveedor del exterior',9=>'Cliente del exterior',10=>'IVA Liberado – Ley 19.640',13=>'Monotributista social',15=>'IVA no alcanzado',16=>'Monotributo trabajador independiente promovido'];
$docType = ['CUIT'=>80,'CUIL'=>86,'DNI'=>96,'CF'=>99][$customer['document_type']];
$qrData = ['ver'=>1,'fecha'=>$invoice['issue_date'],'cuit'=>(int)$issuer['cuit'],'ptoVta'=>(int)$invoice['point_of_sale'],'tipoCmp'=>(int)$invoice['voucher_type'],'nroCmp'=>(int)$invoice['number'],'importe'=>$totals['total_cents']/100,'moneda'=>'PES','ctz'=>1,'tipoDocRec'=>$docType,'nroDocRec'=>(int)$customer['document_number'],'tipoCodAut'=>'E','codAut'=>(int)$invoice['cae']];
$qrUrl = 'https://www.arca.gob.ar/fe/qr/?p=' . base64_encode(json_encode($qrData,JSON_THROW_ON_ERROR));
$money = static fn(int $cents): string => '$ ' . number_format($cents/100,2,',','.');
$dateFormat = static function(string $date): string { if(preg_match('/^\d{8}$/',$date)){$date=substr($date,0,4).'-'.substr($date,4,2).'-'.substr($date,6,2);} return date('d/m/Y',strtotime($date)); };
?>
<!doctype html><html lang="es-AR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Factura <?= ff_escape($letter) ?> <?= str_pad((string)$invoice['point_of_sale'],5,'0',STR_PAD_LEFT) ?>-<?= str_pad((string)$invoice['number'],8,'0',STR_PAD_LEFT) ?></title><link rel="stylesheet" href="<?= ff_escape($basePath) ?>/assets/print.css"><script defer src="<?= ff_escape($basePath) ?>/assets/qrcode.js"></script><script defer src="<?= ff_escape($basePath) ?>/assets/print.js"></script></head><body>
<nav class="print-tools"><a href="<?= ff_escape($basePath) ?>/">Volver</a><button id="print-button">Imprimir / Guardar PDF</button></nav>
<main class="invoice-sheet">
<?php if($invoice['environment']!=='production'): ?><div class="test-banner">HOMOLOGACIÓN — COMPROBANTE DE PRUEBA SIN VALIDEZ FISCAL</div><?php endif; ?>
<p class="original">ORIGINAL</p><header class="invoice-header"><section><h1><?= ff_escape($issuer['company_name']) ?></h1><p><?= ff_escape($issuer['address'] ?? '') ?><br><?= ff_escape(implode(' · ',array_filter([$issuer['city']??'',$issuer['province']??'']))) ?></p><p><?= ff_escape($conditions[(int)$issuer['issuer_tax_condition']]??'') ?></p></section><div class="voucher-letter"><strong><?= ff_escape($letter) ?></strong><small>Cód. <?= str_pad((string)$invoice['voucher_type'],3,'0',STR_PAD_LEFT) ?></small></div><section><h2>FACTURA</h2><p><b>Punto de venta:</b> <?= str_pad((string)$invoice['point_of_sale'],5,'0',STR_PAD_LEFT) ?><br><b>Comprobante:</b> <?= str_pad((string)$invoice['number'],8,'0',STR_PAD_LEFT) ?><br><b>Fecha:</b> <?= $dateFormat($invoice['issue_date']) ?></p><p><b>CUIT:</b> <?= ff_escape($issuer['cuit']) ?><br><b>Ingresos brutos:</b> <?= ff_escape($issuer['income_tax_number']??'') ?><br><b>Inicio de actividades:</b> <?= !empty($issuer['activity_start'])?$dateFormat($issuer['activity_start']):'' ?></p></section></header>
<section class="customer"><h3><?= ff_escape($customer['name']) ?></h3><p><b><?= ff_escape($customer['document_type']) ?>:</b> <?= ff_escape($customer['document_number']) ?> · <?= ff_escape($conditions[(int)$customer['tax_condition']]??'') ?></p><p><?= ff_escape(implode(' · ',array_filter([$customer['address']??'',$customer['city']??'',$customer['province']??'']))) ?></p><p>Condición de venta: Contado · Moneda: Pesos argentinos</p></section>
<table><thead><tr><th>Código / Descripción</th><th>Cantidad</th><th>Precio unitario<?= !empty($issuer['prices_include_vat'])?' final':' neto' ?></th><?php if($letter!=='C'): ?><th>IVA</th><?php endif; ?><th>Importe final</th></tr></thead><tbody>
<?php foreach($invoice['items'] as $item): ?><tr><td><small><?= ff_escape($item['code']??'') ?></small><br><?= ff_escape($item['name']) ?></td><td><?= ff_escape($item['quantity']) ?></td><td><?= $money((int)$item['unit_price_cents']) ?></td><?php if($letter!=='C'): ?><td><?= ff_escape(str_replace('.',',',$item['vat_rate'])) ?>%</td><?php endif; ?><td><?= $money((int)$item['total_cents']) ?></td></tr><?php endforeach; ?>
</tbody></table><section class="totals">
<?php if($letter!=='C'): ?><p>Neto gravado <b><?= $money((int)$totals['net_cents']) ?></b></p><?php foreach($totals['vat_breakdown'] as $vat): ?><p>IVA <?= ff_escape(str_replace('.',',',(string)$vat['rate'])) ?>% <b><?= $money((int)$vat['vat_cents']) ?></b></p><?php endforeach; ?><?php endif; ?>
<p class="grand-total">TOTAL <b><?= $money((int)$totals['total_cents']) ?></b></p></section>
<footer><div id="fiscal-qr" data-url="<?= ff_escape($qrUrl) ?>" aria-label="Código QR de verificación ARCA"></div><div><h3>Comprobante autorizado</h3><p><b>CAE:</b> <?= ff_escape($invoice['cae']) ?><br><b>Vencimiento CAE:</b> <?= $dateFormat($invoice['cae_due_date']) ?></p><a href="<?= ff_escape($qrUrl) ?>" rel="noopener" target="_blank">Verificar comprobante en ARCA</a></div></footer>
</main></body></html>
